#!/usr/bin/env python3
import base64, io, json, os, pathlib, subprocess, sys, tarfile, secrets

ROOT = pathlib.Path.cwd()
if not (ROOT / "src/lib/holdBuild.ts").exists():
    sys.exit("Run this from ~/shape-lab")
stamp = (ROOT / "src/lib/holdBuild.ts").read_text()
if "HOLD_BUILD = 'Sort'" in stamp:
    sys.exit("This folder is Sort (v2-rebuild). Check out shape-lab-v4 first. Do not merge v2.")
if "Lace" not in stamp:
    print("WARNING: holdBuild is not Lace")

TGZ = """\

"""

raw = base64.b64decode("".join(TGZ.split()))
with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as t:
    t.extractall(ROOT)
print("wrote calendar source files")

def patch(rel, old, new):
    p = ROOT / rel
    text = p.read_text()
    if new[:40] in text:
        print("already patched", rel)
        return
    if old not in text:
        sys.exit(f"PATCH MISS {rel}")
    p.write_text(text.replace(old, new, 1))
    print("patched", rel)

